/* Náčinie sa ODVODZUJE z metaúdajov cviku – nedá sa nakresliť náčinie, ktoré
   cvik nevyžaduje. `rig` (a jeho verzia v ráme) určuje len rozmiestnenie. */
function gearFor(entry, media, frame) {
  const rig = Object.assign({}, media.rig || {}, frame.gear || {});
  const eq = entry.equipment || [];
  const gear = {};
  if (eq.indexOf('barbell') >= 0) gear.barbell = rig.barbell || 'big';
  if (eq.indexOf('dumbbells') >= 0) gear.dumbbells = true;
  if (eq.indexOf('bench') >= 0) gear.bench = rig.bench || { x: 44, y: 87, w: 80 };
  if (eq.indexOf('pullupBar') >= 0) {
    if (media.bars === 'dip') gear.dips = rig.dips || 67;
    else gear.pullup = rig.pullup === undefined ? 22 : rig.pullup;
  }
  if (eq.indexOf('cableMachine') >= 0) {
    if (media.sled) gear.sled = rig.sled;
    else gear.cable = rig.cable || { x: 186, pulleyY: 62 };
  }
  if (eq.indexOf('bands') >= 0 && rig.band) gear.band = rig.band;
  if (rig.box) gear.box = rig.box;
  if (rig.mat) gear.mat = rig.mat;
  return gear;
}

/* Rámy cviku: najprv video (ak je), potom fotografie (ak sú). Bez skutočnej fotky či videa
   vráti null a rozhranie ukáže krátku správu – NIKDY sa nekreslí náhradná schéma.
   Poradie MEDIA_CREDITS[id] musí zodpovedať poradiu týchto rámov. */
function framesForExercise(entry) {
  if (!entry) return null;
  const frames = [];
  const video = EXERCISE_VIDEO_MEDIA[entry.id];
  if (video) frames.push({ video: true, src: video.src, mp4: video.mp4 || '', poster: video.poster, caption: 'media.video' });
  const photos = EXERCISE_PHOTO_MEDIA[entry.id];
  if (photos && photos.length) photos.forEach((p) => frames.push(Object.assign({}, p)));
  return frames.length ? { frames } : null;
}

/* Jeden rám pripravený na vykreslenie (náčinie už je odvodené z metaúdajov). */
function resolvedFrame(entry, media, index) {
  const frame = media.frames[index];
  if (!frame) return null;
  const scene = frame.scene
    || media.scene
    || (entry.locations.indexOf('gym') >= 0 ? 'gym' : (entry.locations.indexOf('home') >= 0 ? 'home' : 'outdoor'));
  const credits = MEDIA_CREDITS[entry.id];
  return Object.assign({}, frame, {
    scene,
    gear: gearFor(entry, media, frame),
    view: frame.view || media.view || 'side',
    credit: (credits && credits[index]) || null,
  });
}

/* Zoznam vizuálov pre galériu. Rám môže byť aj skutočný obrázok ({ src }) –
   vtedy sa použije <img> a všetko ostatné (popisky, ovládanie, offline) funguje rovnako. */
function exerciseMediaList(entry) {
  const media = framesForExercise(entry);
  if (!media) return [];
  return media.frames.map((f, i) => Object.assign({ index: i }, resolvedFrame(entry, media, i)));
}
/* ---------- Plány: prístup, poradie a zobrazované názvy ---------- */

function getPlan(id) {
  return (id && state && state.plans && state.plans[id]) || null;
}

/* Aktívne plány v poradí, ktoré si nastavil používateľ (jediný zdroj pre chipy aj rotáciu). */
function activePlanIds() {
  if (!state || !Array.isArray(state.planOrder)) return [];
  return state.planOrder.filter(id => !!getPlan(id));
}

/* Názov plánu: ručne zmenený názov sa nikdy neprekladá, nedotknutý zabudovaný plán áno. */
function planDisplayName(plan) {
  if (!plan) return t('pokrok.workoutFallback');
  return plan.customName ? plan.customName : t('plan.' + plan.id);
}

function planNameOf(id) {
  return planDisplayName(getPlan(id));
}

/* Názov zapísaný do histórie v čase tréningu – nemenný záznam pre prípad zmazania plánu. */
function recordedPlanName(plan) {
  if (!plan) return '';
  if (plan.customName) return plan.customName;
  return BUILTIN_PLAN_NAMES[plan.id] || t('plan.' + plan.id);
}

/* Názov plánu v histórii: existujúci plán sa prekladá, zmazaný sa berie zo záznamu. */
function historyPlanName(w) {
  const plan = getPlan(w.planId);
  if (plan) return planDisplayName(plan);
  if (w.planName) return w.planName;
  return t('pokrok.workoutFallback');
}

function exerciseDisplayName(ex) {
  return (ex && ex.id && BUILTIN_EXERCISE_IDS.has(ex.id)) ? t('exercise.' + ex.id) : ex.name;
}

function recordedNameToDisplay(name) {
  const id = BUILTIN_NAME_TO_ID[name];
  return id ? t('exercise.' + id) : name;
}

/* Názov cviku zapísaný do histórie. Pre zabudovaný cvik je to neutrálny anglický
   záznam (referenčný slovník), takže história zostane čitateľná aj vtedy, keď sa
   neskôr zmení preklad alebo sa cvik z knižnice vyradí. */
function recordedExerciseName(ex) {
  const id = builtinExerciseId(ex);
  if (id) return (I18N.en && I18N.en['exercise.' + id]) || ex.name || id;
  return String(ex.name == null ? '' : ex.name);
}

